SELECT gen_random_uuid()::text, 'formula', '$V_o \approx \frac{V_{ex}\,GF\,\varepsilon}{4}$', 'Strain Gauge Bridge Output', '$GF = \frac{\Delta R/R}{\varepsilon},\qquad V_o \approx \frac{V_{ex}\,GF\,\varepsilon}{4}\ (\text{quarter bridge})$', '$\text{V}$', 'A strain gauge changes resistance with strain; a Wheatstone bridge turns that into a small voltage.', '[{"symbol":"$GF$","meaning":"gauge factor, about 2 for metal foil","unit":null},{"symbol":"$\\varepsilon$","meaning":"strain","unit":null},{"symbol":"$V_{ex}$","meaning":"bridge excitation","unit":"$\\text{V}$"}]'::jsonb, 'Half and full bridges give 2 and 4 times the output and cancel temperature drift.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Instrumentation & Control' AND t."subject" = 'EE' AND s."normKey" = 'transducers and sensors' AND s."active"), NULL, false, 'PENDING', now(), now()
