SELECT gen_random_uuid()::text, 'formula', '$R_T = R_0(1 + \alpha T)$', 'RTD Resistance', '$R_T = R_0(1 + \alpha T),\qquad \alpha = 0.00385\ /^\circ\text{C}\ (\text{Pt100})$', '$\Omega$', 'A platinum resistance thermometer''s resistance rises almost linearly with temperature.', '[{"symbol":"$R_0$","meaning":"resistance at 0 °C (100 Ω for Pt100)","unit":"$\\Omega$"},{"symbol":"$T$","meaning":"temperature","unit":"$\\text{°C}$"}]'::jsonb, 'Lead resistance adds error: use 3- or 4-wire connections.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Instrumentation & Control' AND t."subject" = 'EE' AND s."normKey" = 'transducers and sensors' AND s."active"), NULL, false, 'PENDING', now(), now()
