SELECT gen_random_uuid()::text, 'formula', '$V = S(T_h - T_c)$', 'Thermocouple EMF', '$V \approx S(T_{hot} - T_{ref});\qquad V_{T_1T_3} = V_{T_1T_2} + V_{T_2T_3}\ (\text{intermediate temperatures})$', '$\text{µV}$', 'A thermocouple''s voltage depends on the temperature DIFFERENCE between its junctions.', '[{"symbol":"$S$","meaning":"Seebeck coefficient, about 41 µV/°C for type K","unit":"$\\text{µV/°C}$"},{"symbol":"$T_{ref}$","meaning":"reference (cold) junction temperature","unit":"$\\text{°C}$"}]'::jsonb, 'Add the cold-junction emf before converting with the table (cold-junction compensation).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Instrumentation & Control' AND t."subject" = 'EE' AND s."normKey" = 'transducers and sensors' AND s."active"), NULL, false, 'PENDING', now(), now()
